arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => activeSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => activeSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => activeSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => activeSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }
    </main>
</div>

@if (!string.IsNullOrEmpty(toastMessage))
{
    <div class="toast @toastType">
        @toastMessage
        <button class="toast-close" @onclick="DismissToast">✕</button>
    </div>
}

@if (showConfirmDialog)
{
    <div class="dialog-overlay" @onclick="CancelConfirm">
        <div class="dialog" @onclick:stopPropagation="true">
            <h3>@confirmTitle</h3>
            <p>@confirmMessage</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
            </div>
        </div>
    </div>
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Toast
    private string toastMessage = "";
    private string toastType = "";
    private CancellationTokenSource? toastCts;

    // Confirmation dialog
    private bool showConfirmDialog;
    private string confirmTitle = "";
    private string confirmMessage = "";
    private Func<Task>? confirmCallback;

    // Profile state
    private UserProfile? savedProfile;
    private string profileName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileAvatarUrl = "";

    // Notifications state
    private NotificationPrefs? savedNotificationPrefs;
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> allChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool changePasswordExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool twoFactorEnabled;

    // Appearance state
    private AppearanceSettings? savedAppearance;
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private List<string> availableLanguages = new() { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        savedProfile = profileTask.Result;
        ApplyProfile(savedProfile);

        savedNotificationPrefs = notifTask.Result;
        ApplyNotificationPrefs(savedNotificationPrefs);

        securitySettings = securityTask.Result;
        twoFactorEnabled = securitySettings.TwoFactorEnabled;

        savedAppearance = appearanceTask.Result;
        ApplyAppearance(savedAppearance);
    }

    private void ApplyProfile(UserProfile profile)
    {
        profileName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
        profileAvatarUrl = profile.AvatarUrl;
    }

    private void ApplyNotificationPrefs(NotificationPrefs prefs)
    {
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new List<string>(prefs.MutedChannels);
    }

    private void ApplyAppearance(AppearanceSettings settings)
    {
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var updated = new UserProfile(profileName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
    }

    // Notifications actions
    private void ToggleMutedChannel(string channel)
    {
        if (mutedChannels.Contains(channel))
            mutedChannels.Remove(channel);
        else
            mutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, new List<string>(mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        savedNotificationPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(string sessionId, string device)
    {
        confirmTitle = "Revoke Session";
        confirmMessage = $"Are you sure you want to revoke the session on \"{device}\"? The device will be signed out immediately.";
        confirmCallback = async () => await RevokeSession(sessionId);
        showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.", "success");
    }

    private void CancelConfirm()
    {
        showConfirmDialog = false;
        confirmCallback = null;
    }

    private async Task ConfirmAction()
    {
        showConfirmDialog = false;
        if (confirmCallback is not null)
        {
            await confirmCallback();
            confirmCallback = null;
        }
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        savedAppearance = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helpers
    private void ShowToast(string message, string type)
    {
        toastCts?.Cancel();
        toastMessage = message;
        toastType = type;
        toastCts = new CancellationTokenSource();
        _ = AutoDismissToast(toastCts.Token);
    }

    private async Task AutoDismissToast(CancellationToken ct)
    {
        try
        {
            await Task.Delay(4000, ct);
            toastMessage = "";
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        toastCts?.Cancel();
        toastMessage = "";
    }

    // Render fragments for each section
    private RenderFragment ProfileSection => __builder =>
    {
        <h2>Profile Settings</h2>

        <div class="form-section">
            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(profileAvatarUrl))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <p class="avatar-url-display">@profileAvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profileName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="profileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment NotificationsSection => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="form-section">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="emailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="pushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@mutedChannels.Contains(channel)"
                               @onchange="() => ToggleMutedChannel(channel)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment SecuritySection => __builder =>
    {
        <h2>Security Settings</h2>

        <div class="form-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => changePasswordExpanded = !changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(changePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm New Password</label>
                            <input id="confirmPwd" type="password" @bind="confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-label" style="margin-top: 1.5rem;">
                <span>
                    Two-Factor Authentication
                    <span class="status-badge @(twoFactorEnabled ? "enabled" : "disabled")">
                        @(twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </span>
                <label class="switch">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (securitySettings?.LastPasswordChange is not null)
            {
                <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions.Any() == true)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in securitySettings.Sessions)
                        {
